    mock.expectedHeaderReceived(HL7Constants.HL7_VERSION_ID, "2.4");
    mock.expectedHeaderReceived(HL7Constants.HL7_CONTEXT, hl7.getHapiContext());
    mock.expectedHeaderReceived(HL7Constants.HL7_CHARSET, null);
