@Test
public void testSendAMessageToBean() throws Exception {
    MockEndpoint endpoint = getMockEndpoint("mock:result");
    endpoint.expectedBodiesReceived("Completed");
    Map<String, Object> headers = new HashMap<String, Object>();
    headers.put("foo", "bar");
    // this header should not be sent as its value cannot be serialized
    headers.put("binding", new JmsBinding());
    template.sendBodyAndHeaders("activemq:Test.BindingQueue", "SomeBody", headers);
    // lets wait for the method to be invoked
    assertMockEndpointsSatisfied();
    // now lets test that the bean is correct
    MyBean bean = getMandatoryBean(MyBean.class, "myBean");
    assertEquals("body", "SomeBody", bean.getBody());
    Map<?, ?> beanHeaders = bean.getHeaders();
    assertNotNull("No headers!", beanHeaders);
    assertEquals("foo header", "bar", beanHeaders.get("foo"));
    assertNull("Should get a null value", beanHeaders.get("binding"));
}

@Test
public void testSendMessagesThenBrowseQueue() throws Exception {
    // send some messages
    for (int i = 0; i < expectedBodies.length; i++) {
        Object expectedBody = expectedBodies[i];
        template.sendBodyAndHeader("activemq:test.b", expectedBody, "counter", i);
    }
    // now lets browse the queue
    JmsQueueEndpoint endpoint = getMandatoryEndpoint("activemq:test.b?maximumBrowseSize=6", JmsQueueEndpoint.class);
    assertEquals(6, endpoint.getMaximumBrowseSize());
    List<Exchange> list = endpoint.getExchanges();
    LOG.debug("Received: " + list);
    assertEquals("Size of list", 6, endpoint.getExchanges().size());
    int index = -1;
    for (Exchange exchange : list) {
        String actual = exchange.getIn().getBody(String.class);
        LOG.debug("Received body: " + actual);
        Object expected = expectedBodies[++index];
        assertEquals("Body: " + index, expected, actual);
    }
}

