    to.reset();
    to.expectedMessageCount(0);
    //Restart endpoint,
    context.stopRoute("foo");
    KafkaEndpoint kafkaEndpoint = (KafkaEndpoint) from;
    kafkaEndpoint.getConfiguration().setSeekTo("end");
