@Test
public void testCors() throws Exception {
    Exchange out = template.request("http://localhost:" + portNum + "/users/123/basic", new Processor() {

        @Override
        public void process(Exchange exchange) throws Exception {
            exchange.getIn().setHeader(Exchange.HTTP_METHOD, "OPTIONS");
        }
    });
    assertEquals("https://localhost:443", out.getOut().getHeader("Access-Control-Allow-Origin"));
    assertEquals("GET, POST, PUT, DELETE, OPTIONS", out.getOut().getHeader("Access-Control-Allow-Methods"));
    assertEquals("Origin, Accept, Content-Type, Access-Control-Request-Method, Access-Control-Request-Headers", out.getOut().getHeader("Access-Control-Allow-Headers"));
    assertEquals("1234", out.getOut().getHeader("Access-Control-Max-Age"));
}

@Test
public void testRestletProducerGet() throws Exception {
    Exchange exchange = template.request("http://localhost:" + portNum + "/users/123/basic", null);
    // verify no problems have occurred:
    assertFalse(exchange.isFailed());
    Message message = exchange.getOut();
    assertThat(message.getHeader(Exchange.HTTP_RESPONSE_CODE, Integer.class), is(200));
    // verify all header values match those specified in restConfiguration:
    assertThat(message.getHeader("Access-Control-Allow-Origin", String.class), is("https://localhost:443"));
    assertHeaderSet(message, "Access-Control-Allow-Methods", "GET", "POST", "PUT", "DELETE", "OPTIONS");
    assertHeaderSet(message, "Access-Control-Allow-Headers", "Origin", "Accept", "Content-Type", "Access-Control-Request-Method", "Access-Control-Request-Headers");
    assertThat(message.getHeader("Access-Control-Max-Age", Integer.class), is(1234));
}

@Test
public void testCustom() throws Exception {
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() throws Exception {
            restConfiguration().component("restlet").host("localhost").port(portNum).bindingMode(RestBindingMode.json).jsonDataFormat("bla");
            // use the rest DSL to define the rest services
            rest("/users/").post("lives").type(UserPojo.class).outType(CountryPojo.class).route().choice().when().simple("${body.id} < 100").bean(new UserErrorService(), "idToLowError").otherwise().bean(new UserService(), "livesWhere");
        }
    });
    try {
        context.start();
        fail("Should have thrown exception");
    } catch (FailedToCreateRouteException e) {
        assertTrue(e.getCause().getMessage().contains("JsonDataFormat name: bla must not be an existing bean instance from the registry"));
    }
}

@Test
public void testCors() throws Exception {
    // send OPTIONS first which should not be routed
    getMockEndpoint("mock:input").expectedMessageCount(0);
    Exchange out = template.request("http://localhost:" + portNum + "/users/123/basic", new Processor() {

        @Override
        public void process(Exchange exchange) throws Exception {
            exchange.getIn().setHeader(Exchange.HTTP_METHOD, "OPTIONS");
        }
    });
    assertEquals(RestConfiguration.CORS_ACCESS_CONTROL_ALLOW_ORIGIN, out.getOut().getHeader("Access-Control-Allow-Origin"));
    assertEquals(RestConfiguration.CORS_ACCESS_CONTROL_ALLOW_METHODS, out.getOut().getHeader("Access-Control-Allow-Methods"));
    assertEquals(RestConfiguration.CORS_ACCESS_CONTROL_ALLOW_HEADERS, out.getOut().getHeader("Access-Control-Allow-Headers"));
    assertEquals(RestConfiguration.CORS_ACCESS_CONTROL_MAX_AGE, out.getOut().getHeader("Access-Control-Max-Age"));
    assertMockEndpointsSatisfied();
    resetMocks();
    getMockEndpoint("mock:input").expectedMessageCount(1);
    // send GET request which should be routed
    String out2 = template.requestBody("http://localhost:" + portNum + "/users/123/basic", null, String.class);
    assertEquals("123;Donald Duck", out2);
    assertMockEndpointsSatisfied();
}

