    template.asyncCallbackRequestBody(url, "Claus", callback);
    template.asyncCallbackRequestBody(url, "Hadrian", callback);
    template.asyncCallbackRequestBody(url, "Willem", callback);
    // END SNIPPET: e3
    assertMockEndpointsSatisfied();
